import{_ as a,a as s}from"./chunks/jobbench_leaderboard_zh.BSyBEwxT.js";import{c as n,Q as t,j as i,m as o}from"./chunks/framework.t4rEqR7d.js";const b=JSON.parse('{"title":"评测","description":"","frontmatter":{},"headers":[],"relativePath":"zh/benchmarks.md","filePath":"zh/benchmarks.md"}'),p={name:"zh/benchmarks.md"};function r(l,e,h,d,c,g){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="评测" tabindex="-1">评测 <a class="header-anchor" href="#评测" aria-label="Permalink to &quot;评测&quot;">​</a></h1><p>我们用 <code>deepseek-v4-flash</code> 作选手跑了 <a href="https://job-bench.github.io/" target="_blank" rel="noreferrer">JobBench</a>， 对比两条 harness——官方的 <strong>OpenCode</strong> 和 pagentv4 的 <strong>inplace</strong> 模式 （<code>CodeRunner + InplaceBackend</code>）。两条 harness 用同一个选手模型、同一个裁判 （<code>deepseek-v4-pro</code>，temperature 0），只差 harness 和 split 两个变量。</p><div class="warning custom-block"><p class="custom-block-title">裁判与官方榜不同</p><p>官方榜的裁判是 <strong>Grok 4.3</strong>，我们用的是 <strong>deepseek-v4-pro</strong>（和选手同厂，打分偏松）。 所以这里的分数只作内部参考，<strong>不能与官方榜直接横比</strong>，本仓库的两行都标了 <code>*</code>。</p></div><h2 id="opencode-vs-pagentv4" tabindex="-1">OpenCode vs pagentv4 <a class="header-anchor" href="#opencode-vs-pagentv4" aria-label="Permalink to &quot;OpenCode vs pagentv4&quot;">​</a></h2><p>同选手、同裁判，只换 harness。两个 split 上 pagentv4 都领先。</p><p><img src="'+a+'" alt="OpenCode 与 pagentv4 在 JobBench Easy 和 Main split 上的对比——pagentv4 的 micro 分在 Easy 上领先 +4.5，Main 上领先 +1.6"></p><ul><li><strong>Easy split：</strong> pagentv4 <strong>80.0</strong> vs OpenCode 75.5（micro）。</li><li><strong>Main split：</strong> pagentv4 <strong>38.2</strong> vs OpenCode 36.6（micro）。</li><li>Main 上 pagentv4 有 5 个任务 ≥0.8（含 1 个满分），OpenCode 只有 1 个。</li></ul><p><code>micro</code> = 总分 / 满分（按 rubric 权重加权）。<code>macro</code> = 各任务归一化分的等权平均。</p><h2 id="落在-main-榜单的位置" tabindex="-1">落在 Main 榜单的位置 <a class="header-anchor" href="#落在-main-榜单的位置" aria-label="Permalink to &quot;落在 Main 榜单的位置&quot;">​</a></h2><p>官方榜只统计 Main split。把本仓库两条 harness 插进那个排名（裁判口径不同，仅示意）：</p><p><img src="'+s+`" alt="JobBench Main split 排行榜，deepseek-v4-flash 在 pagentv4 下 38.2、OpenCode 下 36.6，落在 GPT-5.5 与 Claude Sonnet 4.6 之间"></p><ul><li><strong>pagentv4 = 38.2</strong>，落在 GPT-5.5（38.3）与 Claude Sonnet 4.6（36.6）之间。</li><li><strong>OpenCode = 36.6</strong>，与 Claude Sonnet 4.6 并列。</li></ul><h2 id="复现" tabindex="-1">复现 <a class="header-anchor" href="#复现" aria-label="Permalink to &quot;复现&quot;">​</a></h2><p>图从 <code>examples/eval/jobbench_scores.json</code> 生成，并写入 <code>examples/eval/</code> 与 <code>docs/public/benchmarks/</code>（VitePress 站点资源）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/aggregate_scores.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/jobbench_scores.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> matplotlib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/plot_jobbench_leaderboard.py</span></span></code></pre></div><p>完整方法论、逐任务明细和运行命令见 <a href="https://github.com/SyncLionPaw/pagent/blob/main/examples/eval/REPORT_jobbench_deepseek-v4-flash.md" target="_blank" rel="noreferrer"><code>examples/eval/REPORT_jobbench_deepseek-v4-flash.md</code></a>。</p>`,16)])])}const v=n(p,[["render",r]]);export{b as __pageData,v as default};
